-- =============================================================================
-- 09_gold_seed_fast_path.sql  |  FAST PATH: load the pre-built Gold CSVs directly
-- Use when you need the Power BI model populated without running 02->04 (e.g. a rehearsal,
-- or the Power BI author working ahead of the live demo). Column order of each CSV matches the
-- DDL in 04 exactly; MATCH_BY_COLUMN_NAME makes the load order-independent anyway.
-- Prerequisite: 01 (setup) and the DDL section of 04 have been run; then
--   PUT file://<pack>/data/gold/*.csv @EDW_GOLD.STAR.STG_GOLD_SEED/ AUTO_COMPRESS=FALSE;
-- Also required BEFORE 03 in the full path: the DIM_* reference seeds (03 copies them into SILVER.REF_*).
-- =============================================================================
USE ROLE ROLE_ELT_ADMIN;
USE WAREHOUSE WH_ELT;
USE SCHEMA EDW_GOLD.STAR;

TRUNCATE TABLE IF EXISTS DIM_DATE;              COPY INTO DIM_DATE              FROM @STG_GOLD_SEED/DIM_DATE.csv              FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_ENTITY;            COPY INTO DIM_ENTITY            FROM @STG_GOLD_SEED/DIM_ENTITY.csv            FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_AIRLINE;           COPY INTO DIM_AIRLINE           FROM @STG_GOLD_SEED/DIM_AIRLINE.csv           FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_STATION;           COPY INTO DIM_STATION           FROM @STG_GOLD_SEED/DIM_STATION.csv           FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_FLIGHT;            COPY INTO DIM_FLIGHT            FROM @STG_GOLD_SEED/DIM_FLIGHT.csv            FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_EMPLOYEE;          COPY INTO DIM_EMPLOYEE          FROM @STG_GOLD_SEED/DIM_EMPLOYEE.csv          FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_COST_CENTER;       COPY INTO DIM_COST_CENTER       FROM @STG_GOLD_SEED/DIM_COST_CENTER.csv       FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_GL_ACCOUNT;        COPY INTO DIM_GL_ACCOUNT        FROM @STG_GOLD_SEED/DIM_GL_ACCOUNT.csv        FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_ASSET;             COPY INTO DIM_ASSET             FROM @STG_GOLD_SEED/DIM_ASSET.csv             FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_MEAL;              COPY INTO DIM_MEAL              FROM @STG_GOLD_SEED/DIM_MEAL.csv              FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS DIM_VENDOR;            COPY INTO DIM_VENDOR            FROM @STG_GOLD_SEED/DIM_VENDOR.csv            FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS FACT_CATERING_UPLIFT;  COPY INTO FACT_CATERING_UPLIFT  FROM @STG_GOLD_SEED/FACT_CATERING_UPLIFT.csv  FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS FACT_FINANCE_POSTING;  COPY INTO FACT_FINANCE_POSTING  FROM @STG_GOLD_SEED/FACT_FINANCE_POSTING.csv  FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS FACT_WORK_ORDER;       COPY INTO FACT_WORK_ORDER       FROM @STG_GOLD_SEED/FACT_WORK_ORDER.csv       FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS FACT_LABOUR_COST;      COPY INTO FACT_LABOUR_COST      FROM @STG_GOLD_SEED/FACT_LABOUR_COST.csv      FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS FACT_AIRLINE_ORDER;    COPY INTO FACT_AIRLINE_ORDER    FROM @STG_GOLD_SEED/FACT_AIRLINE_ORDER.csv    FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS FACT_PURCHASE_ORDER;   COPY INTO FACT_PURCHASE_ORDER   FROM @STG_GOLD_SEED/FACT_PURCHASE_ORDER.csv   FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';

USE SCHEMA EDW_GOLD.AGG;
TRUNCATE TABLE IF EXISTS AGG_DAILY_FLIGHTS;              COPY INTO AGG_DAILY_FLIGHTS              FROM @EDW_GOLD.STAR.STG_GOLD_SEED/AGG_DAILY_FLIGHTS.csv              FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS AGG_MONTHLY_AIRLINE_PNL;        COPY INTO AGG_MONTHLY_AIRLINE_PNL        FROM @EDW_GOLD.STAR.STG_GOLD_SEED/AGG_MONTHLY_AIRLINE_PNL.csv        FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';
TRUNCATE TABLE IF EXISTS AGG_MONTHLY_ASSET_RELIABILITY;  COPY INTO AGG_MONTHLY_ASSET_RELIABILITY  FROM @EDW_GOLD.STAR.STG_GOLD_SEED/AGG_MONTHLY_ASSET_RELIABILITY.csv  FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_HEADER_MATCH') MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE ON_ERROR = 'ABORT_STATEMENT';

-- In the FULL path (02 -> 03 -> 04) only this one seed is needed, because flight-movement history
-- predates the SITA feed window shipped in Bronze:
--   COPY INTO EDW_GOLD.AGG.AGG_DAILY_FLIGHTS FROM @EDW_GOLD.STAR.STG_GOLD_SEED/AGG_DAILY_FLIGHTS.csv ... (run before the MERGE in 04)

SELECT 'DIM_DATE' t, COUNT(*) n FROM EDW_GOLD.STAR.DIM_DATE
UNION ALL SELECT 'DIM_EMPLOYEE', COUNT(*) FROM EDW_GOLD.STAR.DIM_EMPLOYEE
UNION ALL SELECT 'DIM_ASSET', COUNT(*) FROM EDW_GOLD.STAR.DIM_ASSET
UNION ALL SELECT 'DIM_VENDOR', COUNT(*) FROM EDW_GOLD.STAR.DIM_VENDOR
UNION ALL SELECT 'FACT_CATERING_UPLIFT', COUNT(*) FROM EDW_GOLD.STAR.FACT_CATERING_UPLIFT
UNION ALL SELECT 'FACT_FINANCE_POSTING', COUNT(*) FROM EDW_GOLD.STAR.FACT_FINANCE_POSTING
UNION ALL SELECT 'FACT_WORK_ORDER', COUNT(*) FROM EDW_GOLD.STAR.FACT_WORK_ORDER
UNION ALL SELECT 'FACT_LABOUR_COST', COUNT(*) FROM EDW_GOLD.STAR.FACT_LABOUR_COST
UNION ALL SELECT 'FACT_AIRLINE_ORDER', COUNT(*) FROM EDW_GOLD.STAR.FACT_AIRLINE_ORDER
UNION ALL SELECT 'FACT_PURCHASE_ORDER', COUNT(*) FROM EDW_GOLD.STAR.FACT_PURCHASE_ORDER
UNION ALL SELECT 'AGG_DAILY_FLIGHTS', COUNT(*) FROM EDW_GOLD.AGG.AGG_DAILY_FLIGHTS
UNION ALL SELECT 'AGG_MONTHLY_AIRLINE_PNL', COUNT(*) FROM EDW_GOLD.AGG.AGG_MONTHLY_AIRLINE_PNL
UNION ALL SELECT 'AGG_MONTHLY_ASSET_RELIABILITY', COUNT(*) FROM EDW_GOLD.AGG.AGG_MONTHLY_ASSET_RELIABILITY;
